tool.command:
#import os #set $name = os.path.splitext(str($infile.display_name).replace(' ', '_'))[0] ## in case someone names the data testdata. rm /home/Phinch/data/testdata.biom | true && ln -s '$infile' '/home/Phinch/data/${name}.biom' && sed -i "s/'REPLACE_ME'/'${name}.biom'/g" /home/Phinch/scripts/readFile.js && ## Rewrite http→https so hostURL (window.location.pathname-based) uses HTTPS. sed -i "s/http/https/g" /home/Phinch/scripts/readFile.js && ## Write nginx location block: proxy EP_PATH_CLEAN/ → php -S on 127.0.0.1:8080. EP_PATH_CLEAN="\${EP_PATH%/}" && printf 'server {
 listen 80;
 location %s {
 proxy_pass http://127.0.0.1:8080/;
 }
}
' "\${EP_PATH_CLEAN}" > /etc/nginx/sites-available/default && cd /home/Phinch && sh -c 'php -S 127.0.0.1:8080 &' && nginx -g 'daemon off;' 2>&1 > /var/log/phinch.log
